import java.util.*;

class Solution {
  public String solveEquation(String equation) {
    String[] sides = equation.split("=", -1);
    int[] left = parse(sides[0]);
    int[] right = parse(sides[1]);
    int coeff = left[0] - right[0];
    int constant = right[1] - left[1];
    if (coeff == 0) return constant == 0 ? "Infinite solutions" : "No solution";
    return "x=" + (constant / coeff);
  }

  private int[] parse(String expression) {
    int coefficient = 0, constant = 0, sign = 1, i = 0;
    while (i < expression.length()) {
      if (expression.charAt(i) == '+') {
        sign = 1;
        i++;
      } else if (expression.charAt(i) == '-') {
        sign = -1;
        i++;
      }
      int start = i;
      while (i < expression.length() && Character.isDigit(expression.charAt(i))) i++;
      int value = i == start ? 1 : Integer.parseInt(expression.substring(start, i));
      if (i < expression.length() && expression.charAt(i) == 'x') {
        coefficient += sign * value;
        i++;
      } else constant += sign * value;
    }
    return new int[] {coefficient, constant};
  }
}
